insert into public.site_settings (id, name, headline, summary, biography, profile_image, hero_visual_caption, last_updated_label, show_last_updated, footer_text, seo_title, seo_description, status) values (1, 'Farzine Hossen', 'Software Engineer / AI Enthusiast', 'I enjoy building smart, practical solutions to real-world problems.', 'I’m a focused and motivated developer with a passion for software development and artificial intelligence. I enjoy building smart, practical solutions to real-world problems. With a strong understanding of core concepts and hands-on project experience, I’m always eager to learn new things and use technology to make a positive impact.', '/assets/img/profile.png', 'Software development · Artificial intelligence', 'January 31, 2026', false, 'Farzine Hossen', 'Farzine Hossen — Portfolio', 'Software development and artificial intelligence. Explore the work and profile of Farzine Hossen.', 'draft') on conflict do nothing;
