insert into public.projects (id, title, slug, summary, details, technologies, category, cover_image, cover_alt, repository_url, demo_url, download_url, sort_order, status) values ('d0d21f66-65b0-5946-b541-066cddd22fc1', 'Gaibandha Students Association Website', 'gsa-sust', 'Developed a full-stack web platform with a dedicated admin panel for the Gaibandha Student Association at SUST to manage member activities, events, gallery, notices, and member information.', 'Developed a full-stack web platform with a dedicated admin panel for the Gaibandha Student Association at SUST to manage member activities, events, gallery, notices, and member information.
insert into public.projects (id, title, slug, summary, details, technologies, category, cover_image, cover_alt, repository_url, demo_url, download_url, sort_order, status) values ('ffc7c1fb-8a9e-5d9e-8b6c-ff4686eaf33a', 'ICERIE-2025', 'icerie', 'Developed the official website for ICERIE 2025 at SUST to showcase conference details, manage registrations and payments, display schedules, and provide updates for participants and organizers.', 'Developed the official website for ICERIE 2025 at SUST to showcase conference details, manage registrations and payments, display schedules, and provide updates for participants and organizers.
insert into public.projects (id, title, slug, summary, details, technologies, category, cover_image, cover_alt, repository_url, demo_url, download_url, sort_order, status) values ('67eb883f-817a-5275-907c-c38d240d0f29', 'ICAP-2025', 'icap', 'Built the official website for ICAP 2025 at SUST to provide conference information, facilitate participant registration, and manage schedules, announcements, and updates for attendees and organizers.', 'Built the official website for ICAP 2025 at SUST to provide conference information, facilitate participant registration, and manage schedules, announcements, and updates for attendees and organizers.
insert into public.projects (id, title, slug, summary, details, technologies, category, cover_image, cover_alt, repository_url, demo_url, download_url, sort_order, status) values ('c04dd5eb-730b-5f00-a935-32c35e431372', 'Effective-learning through improved prompt design', 'effective-learning', 'Developed a research data collection website utilizing few-shot prompting to gather user responses and feedback for studying effective learning through improved prompt design.', 'Developed a research data collection website utilizing few-shot prompting to gather user responses and feedback for studying effective learning through improved prompt design.
insert into public.projects (id, title, slug, summary, details, technologies, category, cover_image, cover_alt, repository_url, demo_url, download_url, sort_order, status) values ('4c514684-b97f-5dda-b5a6-7d20fc2b72d0', 'FarmAI', 'farm-ai', 'A deep learning-based crop disease detection and prevention system using YOLO, integrated with a related marketplace to support farmers with actionable insights and relevant resources.', 'A deep learning-based crop disease detection and prevention system using YOLO, integrated with a related marketplace to support farmers with actionable insights and relevant resources.
insert into public.projects (id, title, slug, summary, details, technologies, category, cover_image, cover_alt, repository_url, demo_url, download_url, sort_order, status) values ('00b2b1f2-c0cf-506d-8636-9180ba4265a6', 'Chol-Kheli', 'chol-kheli', 'Developed an online auction platform for cricket and football players, featuring live bidding, team and player management, and admin controls to facilitate seamless team formation and tournament setup', 'Developed an online auction platform for cricket and football players, featuring live bidding, team and player management, and admin controls to facilitate seamless team formation and tournament setup
insert into public.projects (id, title, slug, summary, details, technologies, category, cover_image, cover_alt, repository_url, demo_url, download_url, sort_order, status) values ('12963532-d6eb-5e6e-84ef-04b784ce0a1f', 'Lemon Leaf Disease Detection', 'lemon-leaf-disease-detection', 'The Lemon Leaf Disease Detection is a web application that uses a fine-tuned YOLO model to detect diseases in lemon leaves. The application is built using Next.js and utilizes the Roboflow platform for model training and deployment. The dataset used for training the model is sourced from Kaggle, ensuring high-quality data for accurate disease detection.', 'The Lemon Leaf Disease Detection is a web application that uses a fine-tuned YOLO model to detect diseases in lemon leaves. The application is built using Next.js and utilizes the Roboflow platform for model training and deployment. The dataset used for training the model is sourced from Kaggle, ensuring high-quality data for accurate disease detection.
insert into public.projects (id, title, slug, summary, details, technologies, category, cover_image, cover_alt, repository_url, demo_url, download_url, sort_order, status) values ('d36f69da-8331-5b21-8441-739368d71532', 'IICT-SUST', 'iict', 'IICT-SUST is a comprehensive web application designed to facilitate the management of student information, course details, and faculty data for the Institute of Information and Communication Technology (IICT) at Shahjalal University of Science and Technology (SUST). The application features a user-friendly interface that allows students to register, view their courses, and access faculty information. Faculty members can manage their profiles and courses efficiently. The backend is powered by NodeJS with PostgreSQL as the database, ensuring robust data handling and security. The application also integrates Nodemailer for email notifications and Cloudinary for image storage.', 'IICT-SUST is a comprehensive web application designed to facilitate the management of student information, course details, and faculty data for the Institute of Information and Communication Technology (IICT) at Shahjalal University of Science and Technology (SUST). The application features a user-friendly interface that allows students to register, view their courses, and access faculty information. Faculty members can manage their profiles and courses efficiently. The backend is powered by NodeJS with PostgreSQL as the database, ensuring robust data handling and security. The application also integrates Nodemailer for email notifications and Cloudinary for image storage.', array['NextJS','NodeJS','PostgreSQL','Nodemailer','Cloudinary']::text[], 'Web', '/assets/img/project/iict.png', 'IICT-SUST project screenshot', '', 'https://iict-sust-swe.vercel.app/', '', 7, 'draft') on conflict do nothing;
insert into public.projects (id, title, slug, summary, details, technologies, category, cover_image, cover_alt, repository_url, demo_url, download_url, sort_order, status) values ('02b441bb-1629-50ee-b037-f51e222dee96', 'DP-Learning App', 'dp-learning-app', 'This is a mobile application designed to help users learn about design patterns in software development. It provides a user-friendly interface for exploring various design patterns, understanding their concepts, and implementing them in real-world scenarios. The app includes features such as interactive tutorials, code examples, quizzes, and a community forum for discussions. It aims to enhance the learning experience by providing practical insights and hands-on exercises related to design patterns.', 'This is a mobile application designed to help users learn about design patterns in software development. It provides a user-friendly interface for exploring various design patterns, understanding their concepts, and implementing them in real-world scenarios. The app includes features such as interactive tutorials, code examples, quizzes, and a community forum for discussions. It aims to enhance the learning experience by providing practical insights and hands-on exercises related to design patterns.', array['Flutter','Dart','Riverpod','NodeJS','ExpressJS','MongoDB','Google Map','Gemini api']::text[], 'App', '/assets/img/project/vdg.jpg', 'DP-Learning App project screenshot', 'https://github.com/Farzine/Design-Pattern-Learning-App', '', '', 8, 'draft') on conflict do nothing;
insert into public.projects (id, title, slug, summary, details, technologies, category, cover_image, cover_alt, repository_url, demo_url, download_url, sort_order, status) values ('3e34c8cf-a878-5ad1-b3ce-189fac2949d6', 'Candle Stick', 'candle-stick', 'A candlestick chart visualization tool that displays Apple Inc. stock price data using Apache ECharts and shadcn UI components.', 'A candlestick chart visualization tool that displays Apple Inc. stock price data using Apache ECharts and shadcn UI components.
insert into public.projects (id, title, slug, summary, details, technologies, category, cover_image, cover_alt, repository_url, demo_url, download_url, sort_order, status) values ('82cae967-6b75-5f3e-be89-21b6b72d6298', 'Waste Management App', 'waste-management-app', 'The Waste Management App is a mobile application designed to facilitate the management and recycling of waste materials. It provides users with a platform to report waste issues, find recycling centers, and learn about proper waste disposal methods. The app integrates with Firebase for data storage and retrieval, and it uses Google Authentication for secure user login.', 'The Waste Management App is a mobile application designed to facilitate the management and recycling of waste materials. It provides users with a platform to report waste issues, find recycling centers, and learn about proper waste disposal methods. The app integrates with Firebase for data storage and retrieval, and it uses Google Authentication for secure user login.', array['Flutter','Firebase','Google Auth']::text[], 'App', '/assets/img/project/waste.png', 'Waste Management App project screenshot', 'https://github.com/Farzine/waste_management_and_recycle_application', '', '', 10, 'draft') on conflict do nothing;
insert into public.projects (id, title, slug, summary, details, technologies, category, cover_image, cover_alt, repository_url, demo_url, download_url, sort_order, status) values ('3963eb47-7ebc-5b3b-b541-9b11e2a48309', '3D Car Game', 'car', 'Developed a 3D car game using Unity and C#, featuring realistic physics, dynamic environments, and engaging gameplay. The game allows players to experience driving in a virtual world with various terrains and challenges.', 'Developed a 3D car game using Unity and C#, featuring realistic physics, dynamic environments, and engaging gameplay. The game allows players to experience driving in a virtual world with various terrains and challenges.', array['Unity','C#']::text[], 'App', '/assets/img/project/car.png', '3D Car Game project screenshot', '', '', 'https://drive.google.com/file/d/1mmpk6zVzzfXqI4QIMUTt5bzG7AW0BrZU/view?usp=sharing', 11, 'draft') on conflict do nothing;
insert into public.projects (id, title, slug, summary, details, technologies, category, cover_image, cover_alt, repository_url, demo_url, download_url, sort_order, status) values ('4933969a-79ff-599d-96b0-da890ff2fcb2', 'Brick Changer Game', 'brick', 'Developed a Brick Changer game using Java and Java Swing, Here i learn how to use Java Swing for GUI development and implement game logic in Java.', 'Developed a Brick Changer game using Java and Java Swing, Here i learn how to use Java Swing for GUI development and implement game logic in Java.', array['Java','Java Swing']::text[], 'App', '/assets/img/project/brick.png', 'Brick Changer Game project screenshot', 'https://github.com/Farzine/Brick-Changer-Game', '', '', 12, 'draft') on conflict do nothing;
insert into public.projects (id, title, slug, summary, details, technologies, category, cover_image, cover_alt, repository_url, demo_url, download_url, sort_order, status) values ('4dd1e236-bf51-59e3-a4bf-fa132f0e9373', 'Golf Game with SFML', 'golf', 'Developed a console golf game using C++ and the SFML library, featuring realistic physics, multiple levels, and engaging gameplay.', 'Developed a console golf game using C++ and the SFML library, featuring realistic physics, multiple levels, and engaging gameplay.', array['C++','SFML library']::text[], 'App', '/assets/img/project/golf.png', 'Golf Game with SFML project screenshot', 'https://github.com/Farzine/Golf_Game_SFML_GAME', '', '', 13, 'draft') on conflict do nothing;
insert into public.projects (id, title, slug, summary, details, technologies, category, cover_image, cover_alt, repository_url, demo_url, download_url, sort_order, status) values ('a96fea96-df0f-5250-b2ac-f62e74b24907', 'Console Snake Game', 'snake', 'Developed a console-based Snake game using C++ and the Graphics.h library, featuring classic gameplay mechanics, dynamic levels, and engaging user interaction. The game allows players to control the snake, collect food, and grow in size while avoiding collisions.', 'Developed a console-based Snake game using C++ and the Graphics.h library, featuring classic gameplay mechanics, dynamic levels, and engaging user interaction. The game allows players to control the snake, collect food, and grow in size while avoiding collisions.', array['C++','Graphics.h library']::text[], 'App', '/assets/img/project/snake.png', 'Console Snake Game project screenshot', 'https://github.com/Farzine/first-snake-game-project-semester-1-2', '', '', 14, 'draft') on conflict do nothing;
insert into public.experiences (id, organization, role, date_label, bullets, url, sort_order, status) values ('d5fa8564-23d9-57fb-8f54-949c8528ae45', 'Kite Games Studio', 'Software Engineer Intern (Machine Learning)', 'Nov 2025 - Feb 2026', array['Fine-tuned DL models like Kontext.dev, using LoRA, improving model efficiency for in-house projects.','Applied prompt engineering techniques to optimize generative AI outputs for game-related applications.','Documented workflows and presented findings to the team, ensuring reproducibility and knowledge transfer.']::text[], 'https://kitegamesstudio.com/', 0, 'draft') on conflict do nothing;
insert into public.experiences (id, organization, role, date_label, bullets, url, sort_order, status) values ('af90775d-aa0c-54cb-8bcb-ba54a8901dba', 'App-concept.com GmbH', 'Software Engineer Intern (Frontend)', 'May 2025 - Oct 2025', array['Built and maintained responsive web applications using Next.js, enhancing user experience and performance.','Implemented reusable UI components and optimized state management.','Worked closely with designers using Figma to translate wireframes into production-ready features.']::text[], 'https://app-concept.com/', 1, 'draft') on conflict do nothing;
